package android.database.sqlite;
import android.content.ContentValues;
import android.database.Cursor;
import java.sql.*;
import java.util.*;
/** Actual native SQLite via JDBC. Records Java SQLite API calls with controlled stage ownership. */
public class SQLiteDatabase implements AutoCloseable {
    public static final int CONFLICT_IGNORE=4,CONFLICT_REPLACE=5,OPEN_READONLY=1;
    public static final List<String> trace=Collections.synchronizedList(new ArrayList<>());
    public static volatile String stage="BOOTSTRAP";
    public final Connection jdbc;private boolean successful;
    public interface CursorFactory{}
    public SQLiteDatabase(Connection connection){jdbc=connection;}
    private static void log(String method,String sql){trace.add(stage+"\t"+method+"\t"+sql.replace('\n',' ').replace('\r',' ').replace('\t',' '));}
    private PreparedStatement prepare(String sql,Object[] args)throws SQLException{PreparedStatement statement=jdbc.prepareStatement(sql);if(args!=null)for(int i=0;i<args.length;i++){Object value=args[i];statement.setObject(i+1,value instanceof Boolean?((Boolean)value?1:0):value);}return statement;}
    public void execSQL(String sql){execSQL(sql,new Object[0]);}
    public void execSQL(String sql,Object[] args){log("execSQL",sql);try(PreparedStatement statement=prepare(sql,args)){statement.execute();}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public Cursor rawQuery(String sql,String[] args){log("rawQuery",sql);try(PreparedStatement statement=prepare(sql,args);ResultSet result=statement.executeQuery()){List<Object[]> rows=new ArrayList<>();List<String> names=new ArrayList<>();int count=result.getMetaData().getColumnCount();for(int i=1;i<=count;i++)names.add(result.getMetaData().getColumnLabel(i));while(result.next()){Object[] row=new Object[count];for(int i=0;i<count;i++)row[i]=result.getObject(i+1);rows.add(row);}return new Rows(rows,names);}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public long insertWithOnConflict(String table,String nullColumn,ContentValues values,int conflict){StringJoiner columns=new StringJoiner(","),slots=new StringJoiner(",");List<Object> args=new ArrayList<>();for(Map.Entry<String,Object> value:values.valueSet()){columns.add('"'+value.getKey()+'"');slots.add("?");args.add(value.getValue());}String sql="INSERT "+(conflict==CONFLICT_IGNORE?"OR IGNORE ":conflict==CONFLICT_REPLACE?"OR REPLACE ":"")+"INTO "+table+"("+columns+") VALUES("+slots+")";log("insert",sql);try(PreparedStatement statement=prepare(sql,args.toArray())){if(statement.executeUpdate()==0)return -1;try(Statement query=jdbc.createStatement();ResultSet result=query.executeQuery("SELECT last_insert_rowid()")){return result.getLong(1);}}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public long insertOrThrow(String table,String nullColumn,ContentValues values){return insertWithOnConflict(table,nullColumn,values,0);}public long insert(String table,String nullColumn,ContentValues values){return insertWithOnConflict(table,nullColumn,values,0);}
    public int update(String table,ContentValues values,String where,String[] whereArgs){StringJoiner assignments=new StringJoiner(",");List<Object> args=new ArrayList<>();for(Map.Entry<String,Object> value:values.valueSet()){assignments.add('"'+value.getKey()+"\"=?");args.add(value.getValue());}if(whereArgs!=null)Collections.addAll(args,(Object[])whereArgs);String sql="UPDATE "+table+" SET "+assignments+(where==null?"":" WHERE "+where);log("update",sql);try(PreparedStatement statement=prepare(sql,args.toArray())){return statement.executeUpdate();}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public int delete(String table,String where,String[] args){String sql="DELETE FROM "+table+(where==null?"":" WHERE "+where);log("delete",sql);try(PreparedStatement statement=prepare(sql,args)){return statement.executeUpdate();}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public boolean inTransaction(){try{return !jdbc.getAutoCommit();}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public void beginTransaction(){log("transaction","BEGIN");try{jdbc.setAutoCommit(false);successful=false;}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public void setTransactionSuccessful(){successful=true;}
    public void endTransaction(){log("transaction",successful?"COMMIT":"ROLLBACK");try{if(successful)jdbc.commit();else jdbc.rollback();}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}finally{successful=false;try{jdbc.setAutoCommit(true);}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}}
    public boolean isReadOnly(){return false;}public boolean isOpen(){try{return !jdbc.isClosed();}catch(SQLException failure){return false;}}public String getPath(){try{return jdbc.getMetaData().getURL().substring("jdbc:sqlite:".length());}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}public void close(){try{jdbc.close();}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    public static SQLiteDatabase openDatabase(String path,CursorFactory factory,int flags){try{return new SQLiteDatabase(DriverManager.getConnection("jdbc:sqlite:"+path));}catch(SQLException failure){throw new SQLiteException(failure.getMessage());}}
    static final class Rows implements Cursor {
        final List<Object[]> rows;final List<String> names;int at=-1;Rows(List<Object[]> rows,List<String> names){this.rows=rows;this.names=names;}Object value(int i){return rows.get(at)[i];}
        public boolean moveToNext(){return ++at<rows.size();}public boolean moveToFirst(){at=0;return !rows.isEmpty();}public String getString(int i){return value(i)==null?null:String.valueOf(value(i));}public long getLong(int i){Object value=value(i);return value==null?0:value instanceof Number?((Number)value).longValue():Long.parseLong(value.toString());}public int getInt(int i){return(int)getLong(i);}public double getDouble(int i){Object value=value(i);return value==null?0:value instanceof Number?((Number)value).doubleValue():Double.parseDouble(value.toString());}public byte[] getBlob(int i){return(byte[])value(i);}public int getType(int i){Object value=value(i);return value==null?0:value instanceof byte[]?4:value instanceof Double||value instanceof Float?2:value instanceof Number?1:3;}public boolean isNull(int i){return value(i)==null;}public int getCount(){return rows.size();}public int getColumnIndex(String name){for(int i=0;i<names.size();i++)if(name.equalsIgnoreCase(names.get(i)))return i;return -1;}public int getColumnCount(){return names.size();}public String[] getColumnNames(){return names.toArray(new String[0]);}public void close(){}
    }
}
